phase3_reports <- function(con,directory='docs/phase3') {
  dir.create(directory,recursive=TRUE,showWarnings=FALSE)
  baseline<-phase3_snapshot_connection();on.exit(DBI::dbDisconnect(baseline,shutdown=TRUE))
  before<-DBI::dbGetQuery(baseline,'SELECT g.season,count(*) canonical_shots_before FROM shot_attempts s JOIN games g USING(game_id) GROUP BY g.season')
  shots<-DBI::dbGetQuery(con,"WITH b AS (SELECT g.season,sum(fga) canonical_box_fga FROM team_box_scores t JOIN games g USING(game_id) GROUP BY g.season), c AS (SELECT c.season,count(*) source_fg_candidates,count(*) FILTER(WHERE g.game_id IS NOT NULL) observed_attempts,count(*) FILTER(WHERE g.game_id IS NULL) observations_without_canonical_game,count(*) FILTER(WHERE e.event_id IS NULL) unmatched_source_shot_observations,count(*) FILTER(WHERE c.certification_status!='certified' AND g.game_id IS NOT NULL) noncertified_observed_attempts FROM shot_recovery_candidates c LEFT JOIN games g USING(game_id) LEFT JOIN pbp_events e USING(game_id,event_id) GROUP BY c.season), v AS (SELECT season,count(*) validated_canonical_attempts,count(*) FILTER(WHERE coordinate_status='observed') attempts_with_valid_coordinates,count(*) FILTER(WHERE coordinate_status='source_missing') attempts_missing_coordinates,count(*) FILTER(WHERE coordinate_status='failed_validation') attempts_with_invalid_coordinates,count(*) FILTER(WHERE classification_rule='unique_box_attempt_constraints') values_uniquely_box_constrained,count(*) FILTER(WHERE classification_rule='unique_NBA_event_observation') values_from_existing_nba_observations,count(*) FILTER(WHERE reference_outcome_checked) separately_checked_outcomes FROM certified_shot_attempts GROUP BY season), a AS (SELECT g.season,count(*) canonical_shots_after FROM shot_attempts s JOIN games g USING(game_id) GROUP BY g.season), q AS (SELECT season,count(DISTINCT game_id) FILTER(WHERE status!='match') unresolved_shooting_games FROM shot_recovery_checks GROUP BY season) SELECT b.*,coalesce(c.source_fg_candidates,0) source_fg_candidates,coalesce(c.observed_attempts,0) observed_attempts,coalesce(v.validated_canonical_attempts,0) validated_canonical_attempts,coalesce(v.attempts_with_valid_coordinates,0) attempts_with_valid_coordinates,coalesce(v.attempts_missing_coordinates,0) attempts_missing_coordinates,coalesce(v.attempts_with_invalid_coordinates,0) attempts_with_invalid_coordinates,coalesce(c.unmatched_source_shot_observations,0) unmatched_source_shot_observations,coalesce(c.observations_without_canonical_game,0) observations_without_canonical_game,coalesce(c.noncertified_observed_attempts,0) noncertified_observed_attempts,coalesce(q.unresolved_shooting_games,0) unresolved_shooting_games,coalesce(v.values_uniquely_box_constrained,0) values_uniquely_box_constrained,coalesce(v.values_from_existing_nba_observations,0) values_from_existing_nba_observations,coalesce(v.separately_checked_outcomes,0) separately_checked_outcomes,coalesce(a.canonical_shots_after,0) canonical_shots_after FROM b LEFT JOIN c USING(season) LEFT JOIN v USING(season) LEFT JOIN a USING(season) LEFT JOIN q USING(season) ORDER BY season")
  shots$canonical_shots_before<-before$canonical_shots_before[match(shots$season,before$season)];shots$canonical_shots_before[is.na(shots$canonical_shots_before)]<-0
  shots$added_canonical_attempts<-shots$canonical_shots_after-shots$canonical_shots_before
  shots$observed_minus_box_attempts<-shots$observed_attempts-shots$canonical_box_fga
  shots$certified_recoverable_share<-shots$validated_canonical_attempts/shots$canonical_box_fga
  shots$observed_share<-shots$observed_attempts/shots$canonical_box_fga
  shots$uncertified_box_attempts<-shots$canonical_box_fga-shots$validated_canonical_attempts
  utils::write.csv(shots,file.path(directory,'shot_completeness.csv'),row.names=FALSE,na='')
  discrepancies<-DBI::dbGetQuery(con,"SELECT season,game_id,team_id,metric,observed,expected,status,dataset_id FROM shot_recovery_checks WHERE status!='match' ORDER BY season,game_id,team_id,metric")
  utils::write.csv(discrepancies,file.path(directory,'shot_discrepancies.csv'),row.names=FALSE,na='')
  reasons<-DBI::dbGetQuery(con,"SELECT season,reason,count(*) observations,count(DISTINCT game_id) games FROM shot_recovery_candidates WHERE certification_status!='certified' GROUP BY season,reason ORDER BY season,observations DESC")
  utils::write.csv(reasons,file.path(directory,'shot_exceptions.csv'),row.names=FALSE)
  physical<-function(db)DBI::dbGetQuery(db,"WITH f AS (SELECT game_id,count(*) n,bool_and(passed IS TRUE AND independent IS TRUE) ok FROM reconciliation_checks GROUP BY game_id) SELECT g.season,count(*) canonical_games,count(*) FILTER(WHERE r.possessions_status='reconciled') possession_games,count(*) FILTER(WHERE r.lineups_status='reconciled') lineup_games,count(*) FILTER(WHERE r.possessions_status='reconciled' AND r.lineups_status='reconciled') both_components_games,count(*) FILTER(WHERE r.possessions_status='reconciled' AND r.lineups_status='reconciled' AND f.n=20 AND f.ok) fully_reconciled_games FROM games g LEFT JOIN reconstruction_status r USING(game_id) LEFT JOIN f USING(game_id) GROUP BY g.season ORDER BY g.season")
  a<-physical(con);b<-physical(baseline);for(k in setdiff(names(b),c('season','canonical_games'))) {a[[paste0(k,'_before')]]<-b[[k]][match(a$season,b$season)];a[[paste0(k,'_added')]]<-a[[k]]-a[[paste0(k,'_before')]]}
  utils::write.csv(a,file.path(directory,'reconstruction_completeness.csv'),row.names=FALSE)
  unresolved<-DBI::dbGetQuery(con,"SELECT g.season,g.game_id,coalesce(r.possessions_status,'not_reconstructed') possessions_status,coalesce(r.lineups_status,'not_reconstructed') lineups_status,r.version,r.dataset_id,CASE WHEN NOT EXISTS(SELECT 1 FROM pbp_events e WHERE e.game_id=g.game_id) THEN 'source_missing_or_not_admitted' WHEN EXISTS(SELECT 1 FROM reconciliation_checks c WHERE c.game_id=g.game_id AND c.passed IS FALSE) THEN 'source_totals_disagree' WHEN EXISTS(SELECT 1 FROM pbp_reconciliation_checks c WHERE c.game_id=g.game_id AND c.metric!='fg3a' AND c.passed IS DISTINCT FROM TRUE) THEN 'missing_or_inconsistent_event_totals' ELSE 'physical_sequence_or_lineup_ambiguity' END current_category FROM games g LEFT JOIN reconstruction_status r USING(game_id) WHERE r.possessions_status IS DISTINCT FROM 'reconciled' OR r.lineups_status IS DISTINCT FROM 'reconciled' ORDER BY g.season,g.game_id")
  utils::write.csv(unresolved,file.path(directory,'unresolved_games.csv'),row.names=FALSE,na='')
  utils::write.csv(aggregate(rep(1,nrow(unresolved)),unresolved[c('season','current_category')],sum),file.path(directory,'unresolved_categories.csv'),row.names=FALSE)
  refs<-DBI::dbGetQuery(con,"SELECT g.season,c.metric,c.independent,CASE WHEN c.passed IS TRUE THEN 'match' WHEN c.passed IS FALSE THEN 'mismatch' ELSE 'unavailable' END status,count(*) checks FROM reconciliation_checks c JOIN games g USING(game_id) GROUP BY ALL ORDER BY ALL")
  utils::write.csv(refs,file.path(directory,'cross_source_reconciliation.csv'),row.names=FALSE)
  nba<-DBI::dbGetQuery(con,"WITH l AS (SELECT nba_game_id,min(espn_game_id) game_id FROM historical_game_links GROUP BY nba_game_id HAVING count(DISTINCT espn_game_id)=1), used AS (SELECT DISTINCT reference_snapshot_id snapshot_id,reference_source_row source_row FROM certified_shot_attempts WHERE reference_snapshot_id IS NOT NULL) SELECT s.season,count(*) nba_source_shot_observations,count(*) FILTER(WHERE g.game_id IS NOT NULL) nba_observations_in_linked_canonical_games,count(*) FILTER(WHERE used.source_row IS NOT NULL) nba_observations_linked_to_certified_attempts,count(*) FILTER(WHERE used.source_row IS NULL) nba_observations_without_certified_attempt_link FROM historical_shots s LEFT JOIN l ON s.game_id=l.nba_game_id LEFT JOIN games g ON l.game_id=g.game_id LEFT JOIN used ON s.snapshot_id=used.snapshot_id AND s.source_row=used.source_row GROUP BY s.season ORDER BY s.season")
  utils::write.csv(nba,file.path(directory,'nba_shot_link_coverage.csv'),row.names=FALSE)
  invisible(list(shots=shots,reconstruction=a))
}
